import type {LessonAssignment,LessonQuestion,LessonSection} from './catalog'
import {investigationById} from './investigation-definitions'
type Q=Omit<LessonQuestion,'id'|'part'>
type Section={title:string;stop:string;learn:string;questions:Q[]}
const T={measure:'foundations.measurement-precision',words:'u1.vocab-position-distance-displacement',slope:'u1.capture-pt-graph',graphs:'u1.read-vt-graph-components',predict:'u1.predict-position-uncertainty',vectors:'u1.vectors-tip-to-tail',accel:'u1.acceleration-rate-of-change',equations:'u1.pick-equation-of-motion',inertia:'u1.newtons-first-law-inertia',identify:'u1.identify-forces',mass:'u1.lab-accel-vs-mass',force:'u1.lab-accel-vs-force',fma:'u1.fma-solve-net-force',third:'u1.third-law-pairs',fbd:'u1.draw-fbd',net:'u1.net-force-from-fbd',friction:'u1.friction-static-kinetic',balance:'u1.equilibrium-find-unknown',incline:'u1.d17-incline-components'}
const w=(prompt:string,explanation:string,extra:Partial<Q>={}):Q=>({prompt,explanation,hint:'Answer each requested part. When the question asks for trial evidence, name the conditions and use the recorded values to support your explanation.',...extra})
const n=(prompt:string,answer:number,unit:string,explanation:string,tolerance=0.03):Q=>({prompt,answer,unit,explanation,tolerance,hint:'Check which trial and time the question names. Write the relevant equation, substitute values with consistent units, and check whether the answer needs a direction or sign.'})
const predict=(prompt:string):Section=>({title:'Make a prediction',stop:'Predict',learn:'Before changing the simulation, write your prediction and explain why you think it will happen. A prediction is not graded for correctness; use the later trials to test it.',questions:[w(prompt,'A prediction with reasoning is diagnostic, not scored right or wrong.',{reflection:true})]})
const run=(title:string,learn:string,questions:Q[]):Section=>({title,stop:'Investigate & record',learn,questions})
const compare=(title:string,learn:string,questions:Q[]):Section=>({title,stop:'Compare & explain',learn,questions})
const transfer=(learn:string,questions:Q[]):Section=>({title:'Try a new situation',stop:'Independent transfer',learn,questions:questions.map(q=>({...q,independent:true,hint:''}))})
function lesson(id:string,targets:string[],draft:Section[],note=''):LessonAssignment{
 const lab=investigationById(id);if(!lab)throw Error('Missing investigation '+id)
 const sections:LessonSection[]=draft.map((s,i)=>({...s,learn:s.learn+(i===1?` Open “Change trial conditions” to enter these settings. ${lab.static?'Select “Record trial” for each set of conditions.':'For each trial, select “Run trial” and let it finish (or select “Finish”), then select “Record trial”.'} Open “Notebook” to compare your saved trials.`:''),questions:s.questions.map((q,j)=>({...q,id:`${i+1}${String.fromCharCode(97+j)}`,part:i+1,targets:q.targets??targets}))}))
 return {slug:'simulation-'+id,simulation:id,unit:'unit-1',day:lab.day,title:`${lab.title} · ${lab.question}`,targets,sections,questions:sections.flatMap(s=>s.questions),toolHref:'/simulations/'+id,investigationGroup:lab.group,minutes:lab.minutes,targetNote:`Review the recorded conditions, comparisons, and independent explanations for each target. Predictions are diagnostic. Completion and a generated table alone are not mastery evidence. ${note}`.trim()}
}
